import re
import pandas as pd

def money(x):
    if isinstance(x, (int, float)): return float(x)
    s = str(x).lower().replace('đ', '').replace(' ', '')
    m = re.fullmatch(r'([\d,.]*)tr(\d*)', s)
    if m: return float(m[1].replace(',', '.') or 0) * 1e6 + float(m[2] or 0) * 1e3
    if s.endswith('k'): return float(s[:-1].replace(',', '.')) * 1e3
    return float(re.sub(r'\D', '', s) or 'nan')

def to_day(x):  # Excel serial number or text date (dd/mm/yyyy, yyyy-mm-dd)
    n = pd.to_numeric(x, errors='coerce')
    if pd.notna(n) and n > 1000:
        return pd.Timestamp('1899-12-30') + pd.Timedelta(days=n)
    return pd.to_datetime(x, dayfirst=True, errors='coerce')

