import re, unicodedata, math
import pandas as pd

def money(x):
    s = str(x).strip().lower().replace('đ', '').replace(' ', '')
    mult = 1.0
    if s.endswith('tr'): s, mult = s[:-2].replace(',', '.'), 1e6
    elif s.endswith('k'): s, mult = s[:-1].replace('.', '').replace(',', '.'), 1e3
    else: s = s.replace('.', '').replace(',', '')
    try: return float(s) * mult
    except ValueError: return float('nan')

def norm(s):
    s = unicodedata.normalize('NFD', str(s).lower().replace('đ', 'd'))
    return re.sub(r'\s+', ' ', s.encode('ascii', 'ignore').decode()).strip()

rh = lambda x: int(math.floor(x + 0.5))  # round half up

